import{z as i,x as B,o,c as A,q as p,j as t,D as E,d as l,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"负利率与移位模型","description":"","frontmatter":{"title":"负利率与移位模型","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/shifted-lognormal-negative-rates.md","filePath":"quant/shifted-lognormal-negative-rates.md","lastUpdated":1791413859000}'),d={name:"quant/shifted-lognormal-negative-rates.md"};function m(h,a,g,F,u,f){const r=B("Mermaid");return o(),A("div",null,[a[2]||(a[2]=p('<h1 id="负利率与移位模型" tabindex="-1">负利率与移位模型 <a class="header-anchor" href="#负利率与移位模型" aria-label="Permalink to &quot;负利率与移位模型&quot;">​</a></h1><div class="epigraph"><p>对数正态在零处有吸收壁；利率一旦可以是负的，Black 公式与 SABR 的 $F^\\beta$ 都要先平移，或改用正态 Bachelier。</p><footer>—— Bachelier, Théorie de la Spéculation, 1900；移位对数正态见利率市场在 2014–2015 年后的报价惯例</footer></div><p><a href="/quant/sabr-lmm-calib">上一课</a>的 SABR-LMM 还默认远期为正。2014 年后欧元、日元互换率进入负值，lognormal Black 的 \\(\\ln F\\) 与 \\(\\alpha/F^{1-\\beta}\\) 崩溃。本课缺口是<strong>坐标再换一次</strong>：Bachelier 正态波动（bp vol）与移位对数正态 \\(F+s\\)。这是衍生品进阶最后一课；下一课程从组合的 Merton 实现接上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Black-76 要求 \\(F\\gt 0\\)。\\(F\\le0\\) 时 ATM caplet 仍在交易，市场改报 normal vol \\(\\sigma_N\\)，使价格等于 Bachelier 公式。移位模型用 \\(\\ln(F+s)\\)，把壁移到 \\(-s\\)。问题是：两套报价并存，转换依赖模型（同一价格对应的 \\(\\sigma_N\\) 与 \\(\\sigma_{LN}\\) 不是常数比）。校准必须先锁定惯例，见 <a href="/quant/quoting-conventions">报价惯例</a>，再谈 SABR。</p><p><span class="marginnote">术语翻译：bp vol 就是「以基点为单位的正态波动率」——报 100 bp vol，意思是一年期远期利率的标准差约为 1%。它不需要对 \\(F\\) 取对数，所以 \\(F\\) 穿过零、变负时公式照样成立。</span></p><p>移位 \\(s\\) 是参数：太小，负利率一深又撞壁；太大，微笑形状被扭曲，\\(\\beta\\) 的含义改变。\\(s\\) 应相对历史最低与期权翼部来选，并隔日稳定，不要每天当自由参数——否则又是校准多峰。</p><p><span class="marginnote">数字实例：若欧元基准利率历史最低约 \\(-0.6\\%\\)、期权翼部隐含到 \\(-1.5\\%\\)，取 \\(s=2\\%\\) 就把吸收壁放在 \\(-2\\%\\)，两头都罩住；若只取 \\(s=0.1\\%\\)，利率一探到 \\(-0.1\\%\\) 就撞壁，对数正态波动率立刻爆炸。</span></p><h3 id="正态不是「零利率的极限」那么干净" tabindex="-1">正态不是「零利率的极限」那么干净 <a class="header-anchor" href="#正态不是「零利率的极限」那么干净" aria-label="Permalink to &quot;正态不是「零利率的极限」那么干净&quot;">​</a></h3><p>\\(F\\to0\\) 时 lognormal vol 爆炸，normal vol 仍有限。但这不表示动态真是算术布朗：长期正态允许利率任意负，概率质量在很负的区域过大。移位对数正态在 \\(-s\\) 有壁，更像「有下界的正变量」。选择是模型风险，应报两套对冲比。</p><p><span class="marginnote">股权可以忽略移位；FX 即期为正也不需要。只有利率（及部分通胀、价差）才把移位当默认。不要把本课写成权重量化或神经网络量化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内部价格用 Bachelier 或 shifted SABR（Hagan 公式的移位版）。网格：swaption 的 ATM 用 \\(\\sigma_N\\) 或 shifted \\(\\alpha\\)。LMM：对 \\(L_i+s\\) 建对数动态，或对 \\(L_i\\) 建正态动态（Bachelier LMM），相关校准对象跟着变。对冲：bp DV01 与 bp Vega 是交易员语言；内部 AAD 应对移位后的状态，再映回 bp。</p><p>负利率下 floor 不再是「几乎无价值的下侧」，虚值 floor 可以很贵。这改变结构票据里的利率保底腿。</p>',14)),(o(),t(s,null,{default:E(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%94%B6%E5%88%B0%E4%B8%80%E4%B8%AA%20swaption%20%E6%88%96%20caplet%20%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20W%7B%22%E6%8A%A5%E4%BB%B7%E6%98%AF%E5%93%AA%E7%A7%8D%20vol%3F%22%7D%0A%20%20W%20--%3E%7C%22normal%20bp%20vol%22%7C%20B%5B%22%E7%9B%B4%E6%8E%A5%E7%94%A8%20Bachelier%20%E6%AD%A3%E6%80%81%E5%85%AC%E5%BC%8F%22%5D%0A%20%20W%20--%3E%7C%22shifted%20lognormal%22%7C%20C%5B%22%E5%85%88%E7%A1%AE%E8%AE%A4%E5%AF%B9%E6%96%B9%E7%9A%84%E7%A7%BB%E4%BD%8D%20s%20%E5%86%8D%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20B%20--%3E%20D%5B%22%E6%8D%A2%E7%AE%97%E5%88%B0%E5%86%85%E9%83%A8%E7%BB%9F%E4%B8%80%E6%83%AF%E4%BE%8B%22%5D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E5%90%8C%E4%B8%80%E6%83%AF%E4%BE%8B%E4%B8%8B%E5%81%9A%20PCA%20%E4%B8%8E%20vega%20%E5%88%86%E6%A1%B6%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AF%B9%E5%86%B2%E6%AF%94%E6%8C%89%E5%86%85%E9%83%A8%E7%8A%B6%E6%80%81%E7%AE%97%E5%86%8D%E6%98%A0%E5%9B%9E%20bp%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「换成 Bachelier 就一劳永逸」。正态模型允许利率负到没有经济意义的深度（如 \\(-100\\%\\)），深度负值区要截断，并把截断对 cap 与 floor 价格的影响写进模型风险报告。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"几何布朗在 0 不可达或吸收（视参数），不能生成负值。市场要负值，就必须换扩散的状态变量：\\(F\\) 本身（正态）或 \\(F+s\\)（移位）。微笑的 \\(\\rho,\\nu\\) 在新坐标下重新解释：同样的风险反转，在 \\(\\sigma_N\\) 与 \\(\\sigma_{LN}\\) 里数字不同。PCA 与桶必须在同一惯例下做，混用会造出假的倾斜因子。",-1)),(o(),t(s,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Neg%5B%22F%20%E5%8F%AF%E4%BB%A5%E4%B8%BA%E8%B4%9F%22%5D%20--%3E%20Bac%5B%22Bachelier%20%E6%AD%A3%E6%80%81%20bp%20vol%22%5D%0A%20%20Neg%20--%3E%20Sh%5B%22%E7%A7%BB%E4%BD%8D%20%E5%AF%B9%E6%95%B0%E6%AD%A3%E6%80%81%20F%20%E5%8A%A0%20s%22%5D%0A%20%20Bac%20--%3E%20Conv%5B%22%E5%90%8C%E4%B8%80%E4%BB%B7%E6%A0%BC%20%E4%B8%A4%E5%A5%97%20%CF%83%20%E4%B8%8D%E5%8F%AF%E7%BA%BF%E6%80%A7%E6%8D%A2%22%5D%0A%20%20Sh%20--%3E%20Conv%0A%20%20Conv%20--%3E%20LMM%5B%22LMM%20%E7%8A%B6%E6%80%81%E9%80%89%20F%20%E6%88%96%20F%20%E5%8A%A0%20s%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e("h2",{id:"边界",tabindex:"-1"},[l("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[7]||(a[7]=e("p",null,"\\(s\\) 的改变会移动所有希腊值，属于模型变更，要走模型风险流程。深度负值与高 vol 下正态模型的利率可以负到没有经济意义，应截断并承认截断对 cap 的影响。RFR 复合后的有效 \\(F\\) 仍可为负。本课结束利率微笑坐标；组合课不再假设你可以随时用 lognormal 债券期权。",-1)),a[8]||(a[8]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[9]||(a[9]=e("ul",null,[e("li",null,"负利率迫使 Bachelier 或移位对数正态；Black 的 \\(\\ln F\\) 不能用。"),e("li",null,"\\(\\sigma_N\\) 与 \\(\\sigma_{LN}\\) 不可常数换算；\\(s\\) 应稳定少动。"),e("li",null,"LMM/SABR 的状态与对冲桶都要在同一惯例下。"),e("li",null,"出处：Bachelier, 1900；移位 SABR 与 bp vol 为 2014 年后市场惯例。")],-1))])}const b=i(d,[["render",m]]);export{c as __pageData,b as default};
